import{_ as n,a0 as p,w as m,s as l,ao as i,I as s,a1 as r,A as o,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux有問必答：如何檢查Linux的內存使用狀況 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何檢查Linux的內存使用狀況 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何檢查Linux的內存使用狀況 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何檢查Linux的內存使用狀況 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150122 Linux FAQs with Answers--How to check memory usage on Linux","title":"Linux有問必答：如何檢查Linux的內存使用狀況","tag":"201502","desc":""},"relativePath":"201502/20150122 Linux FAQs with Answers--How to check memory usage on Linux.md","filePath":"[post].md"}'),c={name:"201502/20150122 Linux FAQs with Answers--How to check memory usage on Linux.md"};function d(h,t,f,u,_,x){const a=p("Link");return m(),l("div",null,[t[13]||(t[13]=i(`<h1 id="linux有問必答-如何檢查linux的內存使用狀況" tabindex="-1">Linux有問必答：如何檢查Linux的內存使用狀況 <a class="header-anchor" href="#linux有問必答-如何檢查linux的內存使用狀況" aria-label="Permalink to “Linux有問必答：如何檢查Linux的內存使用狀況”">​</a></h1><blockquote><p><strong>問題</strong>：我想要監測Linux系統的內存使用狀況。有哪些可用的圖形界面或者命令列工具來檢查當前內存使用情況？</p></blockquote><p>當涉及到Linux系統性能優化的時候，物理內存是一個最重要的因素。自然的，Linux提供了豐富的選擇來監測珍貴的內存資源的使用情況。不同的工具，在監測粒度（例如：全系統範圍，每個進程，每個用户），接口方式（例如：圖形用户界面，命令列，ncurses）或者運行模式（交互模式，批量處理模式）上都不盡相同。</p><p>下面是一個可供選擇的，但並不全面的圖形或命令列工具列表，這些工具用來檢查Linux平台中已用和可用的內存。</p><h3 id="_1-proc-meminfo" tabindex="-1">1. /proc/meminfo <a class="header-anchor" href="#_1-proc-meminfo" aria-label="Permalink to “1. /proc/meminfo”">​</a></h3><p>一種最簡單的方法是通過“/proc/meminfo”來檢查內存使用狀況。這個動態更新的虛擬文件事實上是諸如free，top和ps這些與內存相關的工具的信息來源。從可用/閒置物理內存數量到等待被寫入緩存的數量或者已寫回磁盤的數量，只要是你想要的關於內存使用的信息，“/proc/meminfo”應有盡有。特定進程的內存信息也可以通過“/proc/&lt;pid&gt;/statm”和“/proc/&lt;pid&gt;/status”來獲取。</p><pre><code>$ cat /proc/meminfo
</code></pre><p><img src="https://farm8.staticflickr.com/7483/15989497899_bb6afede11_b.jpg" alt=""></p><h3 id="_2-atop" tabindex="-1">2. atop <a class="header-anchor" href="#_2-atop" aria-label="Permalink to “2. atop”">​</a></h3><p>atop命令是用於終端環境的基於ncurses的交互式的系統和進程監測工具。它展示了動態更新的系統資源摘要（CPU, 內存, 網絡, 輸入/輸出, 內核），並且用醒目的顏色把系統高負載的部分以警告信息標註出來。它同樣提供了類似於top的線程（或用户）資源使用視圖，因此係統管理員可以找到哪個進程或者用户導致的系統負載。內存統計報告包括了總計/閒置內存，緩存的/緩衝的內存和已提交的虛擬內存。</p><pre><code>$ sudo atop
</code></pre><p><img src="https://farm8.staticflickr.com/7552/16149756146_893773b84c_b.jpg" alt=""></p><h3 id="_3-free" tabindex="-1">3. free <a class="header-anchor" href="#_3-free" aria-label="Permalink to “3. free”">​</a></h3><p>free命令是一個用來獲得內存使用概況的快速簡單的方法，這些信息從“/proc/meminfo”獲取。它提供了一個快照，用於展示總計/閒置的物理內存和系統交換區，以及已使用/閒置的內核緩衝區。</p><pre><code>$ free -h
</code></pre><p><img src="https://farm8.staticflickr.com/7531/15988117988_ba8c6b7b63_b.jpg" alt=""></p><h3 id="_4-gnome-system-monitor" tabindex="-1">4. GNOME System Monitor <a class="header-anchor" href="#_4-gnome-system-monitor" aria-label="Permalink to “4. GNOME System Monitor”">​</a></h3><p>GNOME System Monitor 是一個圖形界面應用，它展示了包括CPU，內存，交換區和網絡在內的系統資源使用率的較近歷史信息。它同時也可以提供一個帶有CPU和內存使用情況的進程視圖。</p><pre><code>$ gnome-system-monitor
</code></pre><p><img src="https://farm8.staticflickr.com/7539/15988118078_279f0da494_c.jpg" alt=""></p><h3 id="_5-htop" tabindex="-1">5. htop <a class="header-anchor" href="#_5-htop" aria-label="Permalink to “5. htop”">​</a></h3><p>htop命令是一個基於ncurses的交互式的進程視圖，它實時展示了每個進程的內存使用情況。它可以報告所有運行中進程的常駐內存大小（RSS）、內存中程序的總大小、庫大小、共享頁面大小和髒頁面大小。你可以橫向或者縱向滾動進程列表進行查看。</p><pre><code>$ htop
</code></pre><p><img src="https://farm9.staticflickr.com/8236/8599814378_de071de408_c.jpg" alt=""></p><h3 id="_6-kde-system-monitor" tabindex="-1">6. KDE System Monitor <a class="header-anchor" href="#_6-kde-system-monitor" aria-label="Permalink to “6. KDE System Monitor”">​</a></h3><p>就像GNOME桌面擁有GNOME System Monitor一樣，KDE桌面也有它自己的對口應用：KDE System Monitor。這個工具的功能與GNOME版本極其相似，也就是説，它同樣展示了一個關於系統資源使用情況，以及帶有每個進程的CPU/內存消耗情況的實時歷史記錄。</p><pre><code>$ ksysguard
</code></pre><p><img src="https://farm8.staticflickr.com/7479/15991397329_ec5d786ffd_c.jpg" alt=""></p><h3 id="_7-memstat" tabindex="-1">7. memstat <a class="header-anchor" href="#_7-memstat" aria-label="Permalink to “7. memstat”">​</a></h3><p>memstat工具對於識別正在消耗虛擬內存的可執行部分、進程和共享庫非常有用。給出一個進程識別號，memstat即可識別出與之相關聯的可執行部分、數據和共享庫究竟使用了多少虛擬內存。</p><pre><code>$ memstat -p &lt;PID&gt;
</code></pre><p><img src="https://farm8.staticflickr.com/7518/16175635905_1880e50055_b.jpg" alt=""></p><h3 id="_8-nmon" tabindex="-1">8. nmon <a class="header-anchor" href="#_8-nmon" aria-label="Permalink to “8. nmon”">​</a></h3><p>nmon工具是一個基於ncurses系統基準測試工具，它能夠以交互方式監測CPU、內存、磁盤I/O、內核、文件系統以及網絡資源。對於內存使用狀況而言，它能夠展示像總計/閒置內存、交換區、緩衝的/緩存的內存，虛擬內存頁面換入換出的統計，所有這些都是實時的。</p><pre><code>$ nmon
</code></pre><p><img src="https://farm9.staticflickr.com/8648/15989760117_30f62f4aba_b.jpg" alt=""></p><h3 id="_9-ps" tabindex="-1">9. ps <a class="header-anchor" href="#_9-ps" aria-label="Permalink to “9. ps”">​</a></h3><p>ps命令能夠實時展示每個進程的內存使用狀況。內存使用報告裏包括了 %MEM (物理內存使用百分比), VSZ (虛擬內存使用總量), 和 RSS (物理內存使用總量)。你可以使用“--sort”選項來對進程列表排序。例如，按照RSS降序排序：</p><pre><code>$ ps aux --sort -rss
</code></pre><p><img src="https://farm9.staticflickr.com/8602/15989881547_ca40839c19_c.jpg" alt=""></p><h3 id="_10-smem" tabindex="-1">10. smem <a class="header-anchor" href="#_10-smem" aria-label="Permalink to “10. smem”">​</a></h3>`,41)),s("p",null,[r(a,{href:"http://xmodulo.com/visualize-memory-usage-linux.html"},{default:o(()=>[...t[0]||(t[0]=[e("smem",-1)])]),_:1}),t[1]||(t[1]=e("命令允許你測定不同進程和用户的物理內存使用狀況，這些信息來源於“/proc”目錄。它利用“按比例分配大小（PSS）”指標來精確量化Linux進程的有效內存使用情況。內存使用分析結果能夠輸出為柱狀圖或者餅圖類的圖形化圖表。",-1))]),t[14]||(t[14]=i(`<pre><code>$ sudo smem --pie name -c &quot;pss&quot;
</code></pre><p><img src="https://farm8.staticflickr.com/7466/15614838428_eed7426cfe_c.jpg" alt=""></p><h3 id="_11-top" tabindex="-1">11. top <a class="header-anchor" href="#_11-top" aria-label="Permalink to “11. top”">​</a></h3><p>top命令提供了一個運行中進程的實時視圖，以及特定進程的各種資源使用統計信息。與內存相關的信息包括 %MEM (內存使用率), VIRT (虛擬內存使用總量), SWAP (換出的虛擬內存使用量), CODE (分配給代碼執行的物理內存數量), DATA (分配給非執行的數據的物理內存數量), RES (物理內存使用總量; CODE+DATA), 和 SHR (有可能與其他進程共享的內存數量)。你能夠基於內存使用情況或者大小對進程列表進行排序。</p><p><img src="https://farm8.staticflickr.com/7464/15989760047_eb8d51d9f2_c.jpg" alt=""></p><h3 id="_12-vmstat" tabindex="-1">12. vmstat <a class="header-anchor" href="#_12-vmstat" aria-label="Permalink to “12. vmstat”">​</a></h3><p>vmstat命令列工具顯示涵蓋了CPU、內存、中斷和磁盤I/O在內的各種系統活動的瞬時和平均統計數據。對於內存信息而言，命令不僅僅展示了物理內存使用情況（例如總計/已使用內存和緩衝的/緩存的內存），還同樣展示了虛擬內存統計數據（例如，內存頁的換入/換出，虛擬內存頁的換入/換出）</p><pre><code>$ vmstat -s
</code></pre><p><img src="https://farm9.staticflickr.com/8582/15988236860_3f142008d2_b.jpg" alt=""></p><hr>`,10)),s("p",null,[t[3]||(t[3]=e("via: ",-1)),r(a,{href:"http://ask.xmodulo.com/check-memory-usage-linux.html"},{default:o(()=>[...t[2]||(t[2]=[e("http://ask.xmodulo.com/check-memory-usage-linux.html",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=e("譯者：",-1)),r(a,{href:"https://github.com/mr-ping"},{default:o(()=>[...t[4]||(t[4]=[e("Ping",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=e("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),r(a,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const L=n(c,[["render",d]]);export{k as __pageData,L as default};
